// Generated by npm run build. Each release installs a complete, versioned app.
const CACHE_PREFIX = 'harnkan:' + new URL(self.registration.scope).pathname + ':';
const CACHE_NAME = CACHE_PREFIX + '__VERSION__';
const ASSETS = __PRECACHE__;
const absolute = path => new URL(path, self.registration.scope).href;

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    try {
      await cache.addAll(ASSETS.map(path => new Request(absolute(path), { cache: 'reload' })));
    } catch (error) {
      await caches.delete(CACHE_NAME);
      throw error;
    }
  })());
});
self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith(CACHE_PREFIX) && key !== CACHE_NAME) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});
self.addEventListener('message', event => {
  if (event.data?.type === 'ACTIVATE_UPDATE') self.skipWaiting();
});
self.addEventListener('fetch', event => {
  const { request } = event;
  const url = new URL(request.url), scope = new URL(self.registration.scope);
  if (request.method !== 'GET' || url.origin !== scope.origin || !url.pathname.startsWith(scope.pathname)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE_NAME);
    // Both /harnkan/ and /harnkan/index.html (with any query) open the same app.
    const entry = request.mode === 'navigate' && (url.pathname === scope.pathname || url.pathname === scope.pathname + 'index.html');
    const cached = await cache.match(entry ? absolute('./index.html') : request, { ignoreSearch: true });
    if (cached) return cached;
    return fetch(request);
  })());
});
